contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint value) public payable {
        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint balAfter = address(c).balance;
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        assert(reverted == (value > balBefore) && balAfter == balBefore - (reverted ? 0 : value) && depositsAfter == depositsBefore);
    }

    receive() external payable {}
}

